import React, { useState, useEffect } from "react";
import { useParams } from "react-router-dom";
import "./DetailsProduct.scss";

const DetailsProduct = () => {
  const { productId } = useParams();
  const [product, setProduct] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchProduct = async () => {
      try {
        const response = await fetch("/products.json");

        if (!response.ok) {
          throw new Error("Erro ao carregar os produtos");
        }

        const data = await response.json();
        const selectedProduct = data.find((p) => String(p.productId) === String(productId));

        console.log("Produto selecionado:", selectedProduct);
        setProduct(selectedProduct);
      } catch (error) {
        console.error("Erro ao carregar o produto:", error);
      } finally {
        setLoading(false);
      }
    };

    fetchProduct();
  }, [productId]);

  if (loading) return <p>Carregando...</p>;
  if (!product) return <p>Produto não encontrado.</p>;

  // Obtendo imagens corretamente
  const images = product.items?.[0]?.images?.map((image) => image.imageUrl) || ["/no-image.jpg"];

  // Obtendo preço à vista e parcelado
  const paymentOption = product?.items?.[0]?.sellers?.[0]?.commertialOffer?.Installments?.[0] || null;
  const priceVista = paymentOption?.TotalValuePlusInterestRate?.toFixed(2) || "Preço não disponível";
  const installments = paymentOption?.NumberOfInstallments || 1;
  const priceParcelado = (paymentOption?.TotalValuePlusInterestRate / installments)?.toFixed(2) || "Preço não disponível";

  return (
    <div className="details-product">
      <div className="product-gallery">
        {images.map((image, index) => (
          <img key={index} src={image} alt={`Produto ${index + 1}`} />
        ))}
      </div>

      <div className="product-info">
        <h1>{product.productName}</h1>
        <p className="description">{product.metaTagDescription || "Sem descrição disponível."}</p>
        
        <p className="price-vista">À vista: R$ {priceVista}</p>
        <p className="price-parcelado">{installments}x de R$ {priceParcelado}</p>

        <button className="add-to-cart">ADICIONAR À SACOLA</button>
      </div>
    </div>
  );
};

export default DetailsProduct;
